from __future__ import annotations
import json,os,subprocess,sys,time
from pathlib import Path
os.environ['CUDA_VISIBLE_DEVICES']=''
REPO=Path(__file__).resolve().parents[1];sys.path.insert(0,str(REPO/'src'))
from vitnns import nns_patch_depth_s4_r12 as r12  # noqa:E402

def git(*args):return subprocess.check_output(['git','-C',str(REPO),*args],text=True).strip()
def main():
 root=REPO/r12.ROOT_REL;r12.require(not root.exists(),'fresh R12 evidence root required');head=git('rev-parse','HEAD');branch=git('symbolic-ref','--short','HEAD');remote=subprocess.check_output(['git','-C',str(REPO),'ls-remote','--heads','origin',f'refs/heads/{branch}'],text=True).split()[0];r12.require(head==remote,'implementation commit not live remote');subprocess.check_call(['git','-C',str(REPO),'merge-base','--is-ancestor','9cec5ddca0cdd8730571ac3e14ddf7fd08c06331',head])
 binding=r12.verify_r11_bindings(REPO);records,identity=r12.verify_selection(REPO);numeric,integrity=r12.compute(REPO,records);r12.require(identity['all_checks_pass'],'corrected identity contract failed');r12.require(integrity['terminal_state_counts']==r12.EXPECTED_STATES,'terminal states drift');r12.require(numeric['endpoint_summaries']['P1']['valid_classes']==120 and numeric['endpoint_summaries']['D1']['valid_classes']==120 and numeric['endpoint_summaries']['P2']['valid_classes']==119,'valid class scopes drift')
 r10_inventory=json.loads((REPO/r12.R11_ROOT_REL/'s4_r10_immutable_root_inventory.json').read_text())['payload'];r11_files=[r12.artifact(REPO,p) for p in sorted((REPO/r12.R11_ROOT_REL).glob('*.json'))];root.mkdir(parents=True)
 correction=r12.signed('s4_r12_selection_anchor_correction_amendment','FROZEN',{'R11_terminal_preserved':True,'R11_terminal_status':'BLOCKED_DATA_INTEGRITY','selected_class_rank_count_correction':{'incorrect':120,'correct':122},'valid_class_counts':{'P1':120,'D1':120,'P2':119},'digest_definition_correction':{'membership_projection_digest':r12.MEMBERSHIP_DIGEST,'membership_projection_fields':['schedule_index','formal_class_rank','source_image_id'],'full_manifest_records_digest':r12.FULL_RECORDS_DIGEST},'selected_source_terminal_array_or_numeric_change_count':0,'endpoint_estimator_threshold_or_decision_rule_change_count':0,'science_changed':False,'outcome_accessed_posthoc':True,'confirmatory_status_restored':False},head)
 binddoc=r12.signed('s4_r12_r11_blocked_terminal_binding','PASS',{'R11_terminal_status':binding['R11_terminal_status'],'R11_files':binding['bound_files'],'R11_root_file_count':len(r11_files),'R11_root_records_digest':r12.canonical_digest(r11_files),'R11_root_records':r11_files,'R10_inventory_file_count':binding['R10_inventory_file_count'],'R10_inventory_records_digest':binding['R10_inventory_records_digest'],'R10_inventory_current_revalidation':{'record_count':len(r10_inventory['records']),'all_files_SHA_and_bytes_pass':all((REPO/x['path']).is_file() and (REPO/x['path']).stat().st_size==x['bytes'] and r12.sha_file(REPO/x['path'])==x['sha256'] for x in r10_inventory['records'])},'R10_R11_mutation_count':0},head)
 identity_doc=r12.signed('s4_r12_corrected_selection_identity_report','PASS',identity,head)
 integrity_doc=r12.signed('s4_r12_input_integrity_report','PASS',{**integrity,'selected_source_count':240,'selected_terminal_count':720,'selected_distinct_class_rank_count':122,'P1_D1_valid_class_count':numeric['endpoint_summaries']['P1']['valid_classes'],'P2_valid_class_count':numeric['endpoint_summaries']['P2']['valid_classes'],'unexplained_failure_count':0,'R10_R11_mutation_count':0},head)
 numeric_doc=r12.signed('s4_r12_endpoint_numeric_recomputation','PASS_POST_HOC_EXPLORATORY',{**numeric,'scientific_scope':'OUTCOME_ACCESSED_POST_HOC_EXPLORATORY','strong_FWER_claimed':False,'original_STOP_SUCCESS_claimed':False},head)
 comparison=r12.signed('s4_r12_original_vs_posthoc_rule_comparison','PASS',{'original_rule':{'P2_point_threshold':0.10,'P2_adjusted_lower_threshold':0.10,'P2_half_width_max':0.015,'checks':numeric['original_P2_rule_checks'],'status':'ORIGINAL_RULE_NOT_PASSED'},'posthoc_rule':{'P2_point_threshold':0.07,'P2_adjusted_lower_threshold':0.0,'P2_half_width_max':0.02,'checks':{k:v for k,v in numeric['posthoc_gate_checks'].items() if k.startswith('P2_')},'status':'PASS_POST_HOC_EXPLORATORY'},'confirmatory_interpretation_allowed':False,'R10_design_eligibility':'HISTORICAL_REFERENCE_ONLY'},head)
 access=r12.signed('s4_r12_cpu_access_and_process_isolation_audit','PASS',{'CUDA_VISIBLE_DEVICES':'','torch_timm_torchvision_PIL_import_count':0,'JPEG_reads':0,'mask_reads':0,'decode_count':0,'model_load_count':0,'checkpoint_reads':0,'CUDA_GPU_initialization_count':0,'process_signal_count':0,'Y4_signal_count':0,'active_S4_production_count_at_start':0,'active_Y4_count_at_start':0,'R11_interruption_audit_verified':True,'D2_formal_test_count':0,'S5_execution_count':0,'S6_execution_count':0},head)
 for name,doc in [('selection_anchor_correction_amendment.json',correction),('r11_blocked_terminal_binding.json',binddoc),('corrected_selection_identity_report.json',identity_doc),('input_integrity_report.json',integrity_doc),('endpoint_numeric_recomputation.json',numeric_doc),('original_vs_posthoc_rule_comparison.json',comparison),('cpu_access_and_process_isolation_audit.json',access)]:r12.write_json_new(root/name,doc)
 print(json.dumps({'status':'PASS','implementation_commit':head,'selected_sources':240,'full_digest':identity['full_manifest_records_digest'],'membership_digest':identity['membership_projection_digest'],'numeric_gates':numeric['all_posthoc_gates_pass']},sort_keys=True));return 0
